/* vl-chrome.js — the ONE place the Verilume utility nav, public header, brand logo and footer links live.
   Every page loads this file instead of carrying its own copy, so a change here shows up on all of them.
   Usage (one tag per spot, nothing else on the page):
     <script src="/vl-chrome.js" data-vl="top-site"></script>   public pages: utility nav + header (inside <div class="sticky-nav-wrap">)
     <script src="/vl-chrome.js" data-vl="utility"></script>    app pages: utility nav only
     <script src="/vl-chrome.js" data-vl="brand"></script>      the logo link (login panel, portal/account night bar)
     <script src="/vl-chrome.js" data-vl="footer"></script>     the footer link row, inside <footer>
   Runs synchronously, so nothing flashes in late. */
(function(){
  var me = document.currentScript; if (!me) return;
  var part = me.getAttribute('data-vl') || '';
  var LOGO = 'data:image/png;base64,';
  var IMG = '<img class="vl-brand-img" src="' + LOGO + '" alt="Verilume" width="640" height="249">';
  var NAV = [
    ['index.html','Humanizing Agentic Marketing'],
    ['media-cx.html','Media + CX'],
    ['aiteam.html','AiTeam Protocol'],
    ['execution.html','Integrated Execution'],
    ['packages.html','Illumination Packages']
  ];
  var CTA = ['assessment.html','Start free assessment'];

  if (!document.getElementById('vl-chrome-css')){
    var st = document.createElement('style'); st.id = 'vl-chrome-css';
    st.textContent =
      '.vl-brand-link{display:inline-block;line-height:0;text-decoration:none;margin:0;background:#FBFAF6;border-radius:12px;padding:6px 16px;}' +
      '.nav .vl-brand-link{margin-right:10px;flex-shrink:0;}' +
      '.vl-brand-img{display:block;height:54px;width:auto;max-width:none;}' +
      '.back-nav .vl-brand-img{height:56px;}' +
      '.login-brand-panel .vl-brand-img{height:64px;}' +
      '@media (max-width:600px){.vl-brand-link{padding:5px 12px;}.vl-brand-img{height:38px;}.back-nav .vl-brand-img{height:40px;}}';
    document.head.appendChild(st);
  }

  var here = (location.pathname.split('/').pop() || 'index.html').toLowerCase();
  function navLinks(){
    return NAV.map(function(n){
      return '<a href="' + n[0] + '"' + (n[0] === here ? ' aria-current="page"' : '') + '>' + n[1] + '</a>';
    }).join('\n        ') + '\n        <a class="nav-cta" href="' + CTA[0] + '">' + CTA[1] + '</a>';
  }
  var UTIL_DIV = "<div class=\"utility-nav\" id=\"utilityNav\">\n  <div class=\"utility-nav-inner\">\n    <a href=\"portal.html\" id=\"utilNavPortalLink\" style=\"display:none;\">Access My Portal</a>\n    <a href=\"login.html\" id=\"utilNavAuthLink\">Log in</a>\n  </div>\n</div>";
  var HEADER = "<header id=\"siteHeader\">\n  <nav class=\"nav\" aria-label=\"Primary\">\n    <a class=\"logo vl-brand-link\" href=\"index.html\" aria-label=\"Verilume home\">" + IMG + "</a>\n    <div class=\"nav-group\">\n      <div class=\"navlinks\" id=\"navLinks\">\n        @@NAV@@\n      </div>\n      <div class=\"nav-right\">\n        <button class=\"nav-toggle\" id=\"navToggle\" aria-label=\"Toggle menu\" aria-expanded=\"false\">\u2630</button>\n      </div>\n    </div>\n  </nav>\n</header>";
  var FOOTER = "<div class=\"footer-inner\">\n    <span>Verilume \u2014 the truth between promise and experience, measured.</span>\n    <nav class=\"footer-nav\" aria-label=\"Footer\">\n      <a href=\"index.html\">Humanizing Agentic Marketing</a>\n      <a href=\"media-cx.html\">Media + CX</a>\n      <a href=\"aiteam.html\">AiTeam Protocol</a>\n      <a href=\"execution.html\">Integrated Execution</a>\n      <a href=\"packages.html\">Illumination Packages</a>\n      <a href=\"licensing.html\">Licensing</a>\n      <a href=\"industry-solutions.html\">Industry Solutions</a>\n    </nav>\n    <span>Design preview</span>\n  </div>";
  function put(html){ me.insertAdjacentHTML('beforebegin', html); }

  if (part === 'top-site' || part === 'utility'){
    put(UTIL_DIV);
    if (!window.__vlUtilReady){
      window.__vlUtilReady = true;

// 2026-08-21 — shared utility-nav logic, identical on every page (see the
// .utility-nav CSS comment for why). Reads a single sessionStorage pointer
// (verilume_active_account) that login.html / assessment.html's Save &
// Schedule flow set on successful sign-in, and that this same script's own
// Logout handler (and every page's own logout(), where one exists) clears.
// Deliberately self-contained (its own vlUtilBackendUrl(), not the page's
// BACKEND_URL) so it works unmodified on pages that don't otherwise talk to
// the backend at all (marketing pages, terms.html, etc.).
(function(){
  function vlUtilBackendUrl(){
    return (typeof window !== 'undefined' && window.location && window.location.protocol !== 'file:')
      ? ''
      : 'http://localhost:8787';
  }
  function vlActiveAccountId(){
    try { return localStorage.getItem('verilume_active_account') || ''; } catch (e) { return ''; }
  }
  function vlUtilityNavInit(){
    var accountId = vlActiveAccountId();
    var portalLink = document.getElementById('utilNavPortalLink');
    var authLink = document.getElementById('utilNavAuthLink');
    if (!portalLink || !authLink) return;
    if (accountId){
      // 2026-08-21 — per direct feedback, showing "Access My Portal" while
      // already ON portal.html is redundant (you're already there); hide
      // it there specifically, still show it everywhere else (marketing
      // pages, assessment.html, account.html, etc.) so there's always a
      // way back to the Portal from outside it.
      var onPortalPage = /\/?portal\.html$/.test((window.location && window.location.pathname) || '');
      if (onPortalPage){
        portalLink.style.display = 'none';
      } else {
        portalLink.href = 'portal.html?accountId=' + encodeURIComponent(accountId);
        portalLink.style.display = '';
      }
      authLink.textContent = 'Logout';
      authLink.href = '#';
      authLink.onclick = function(e){
        e.preventDefault();
        var token = null;
        try { token = localStorage.getItem('verilume_session_' + accountId); } catch (e2) {}
        var finish = function(){
          try {
            localStorage.removeItem('verilume_session_' + accountId);
            localStorage.removeItem('verilume_member_' + accountId);
            localStorage.removeItem('verilume_active_account');
          } catch (e3) {}
          location.href = '/';
        };
        if (token){
          fetch(vlUtilBackendUrl() + '/api/auth/logout', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ token: token })
          }).then(finish).catch(finish);
        } else {
          finish();
        }
      };
    } else {
      portalLink.style.display = 'none';
      authLink.textContent = 'Log in';
      authLink.href = 'login.html';
      authLink.onclick = null;
    }
  }
  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', vlUtilityNavInit);
  } else {
    vlUtilityNavInit();
  }
  // 2026-08-24, per direct report ("Access My Portal takes me to the
  // wrong account, even after logging in as the right one") — this only
  // ever ran once, on initial load. Two real ways that goes stale: (1)
  // the browser restores this exact page from bfcache on Back/Forward
  // navigation, which does NOT re-fire DOMContentLoaded, so the link's
  // href keeps whatever account (or none) was active when this page was
  // first painted, even if a login happened after that in this same tab
  // via a different page; (2) this page was left open in one tab while
  // login happened in another tab/window — localStorage changed, but
  // this tab's DOM never re-read it. 'pageshow' fires on both a normal
  // load AND a bfcache restore (check event.persisted to tell them
  // apart, though re-running is harmless either way); the 'storage'
  // event fires in OTHER tabs of the same origin when localStorage
  // changes in one tab, so both close the gap.
  window.addEventListener('pageshow', function(e){ vlUtilityNavInit(); });
  window.addEventListener('storage', function(e){
    if (!e.key || e.key === 'verilume_active_account') vlUtilityNavInit();
  });
  window.vlUtilityNavInit = vlUtilityNavInit; // exposed so login()/logout() elsewhere can re-run it after changing session state without a full reload
})();

    } else if (window.vlUtilityNavInit) { window.vlUtilityNavInit(); }
  }
  if (part === 'top-site'){
    put(HEADER.replace('@@NAV@@', navLinks()));
  }
  if (part === 'brand'){
    put('<a class="wordmark vl-brand-link" href="index.html" aria-label="Verilume home">' + IMG + '</a>');
  }
  if (part === 'footer'){
    put(FOOTER);
  }
})();
